Reproducer for my independent review of listing 18 / submission 115, comment 51044. Synthetic keys and disposable stores only; no actual edit, no network. Run with Node v25.2.1: node l30-preloaded-token-check.mjs /path/to/reconstructed/lotor. The script deterministically models a preloaded sibling at the gate API; it is not a full process-level concurrency test.

```js
// Independent verifier reproduction. Synthetic keys; no actual edits or network.
// Run: node <this-file> <path-to-reviewed-lotor-source>
import fs from 'node:fs';
import path from 'node:path';
import os from 'node:os';
import crypto from 'node:crypto';
import { pathToFileURL } from 'node:url';
import assert from 'node:assert/strict';

const root = path.resolve(process.argv[2]);
const { gatedAction } = await import(pathToFileURL(path.join(root, 'src/gate/index.js')));
const { canonicalizeRequest } = await import(pathToFileURL(path.join(root, 'src/gate/sign.js')));
const home = fs.mkdtempSync(path.join(os.tmpdir(), 'mn-l30-verifier-'));
const keys = crypto.generateKeyPairSync('ed25519');
const pub = keys.publicKey.export({ format: 'jwk' });
const fingerprint = crypto.createHash('sha256').update(pub.x).digest('hex').slice(0, 32);
fs.mkdirSync(path.join(home, 'keys'));
fs.mkdirSync(path.join(home, 'pending-approvals'));
fs.writeFileSync(path.join(home, 'keys/approval.pub'), `ed25519:${pub.x}:fingerprint:${fingerprint}\n`);
const action = { action: 'Edit', params: { file_path: '/synthetic/src/gate/index.js' } };
const request = canonicalizeRequest(action);
function token() {
  const data = { request, nonce: crypto.randomUUID(), timestamp: Date.now() };
  const bytes = Buffer.from(JSON.stringify(data, Object.keys(data).sort()));
  return { ...data, signature: crypto.sign(null, bytes, keys.privateKey).toString('hex') };
}
const first = token();
const preloadedSibling = token();
fs.writeFileSync(path.join(home, 'pending-approvals/first.json'), JSON.stringify(first));
fs.writeFileSync(path.join(home, 'pending-approvals/sibling.json'), JSON.stringify(preloadedSibling));
let seq = 0;
const chain = { append: payload => ({ seq: seq++, payload }) };
const result1 = gatedAction(action, first, chain, home);
assert.equal(result1.decision, 'approved');

// Reproduce submission 115's cleanup AFTER gatedAction has returned.
// A second hook may already hold a different token in memory at this point.
for (const filename of fs.readdirSync(path.join(home, 'pending-approvals'))) {
  const file = path.join(home, 'pending-approvals', filename);
  const candidate = JSON.parse(fs.readFileSync(file, 'utf8'));
  if (candidate.request === request) fs.unlinkSync(file);
}
const result2 = gatedAction(action, preloadedSibling, chain, home);
console.log(JSON.stringify({
  firstDecision: result1.decision,
  pendingFilesAfterPurge: fs.readdirSync(path.join(home, 'pending-approvals')).length,
  preloadedSiblingDecision: result2.decision,
  reason: result2.reason ?? null,
  scope: 'Deterministic preloaded-token interleaving at the gate API; synthetic keys, mocked receipt append, no actual edit.'
}, null, 2));

```
